/* Start here entry for superfluid-helium (demos/lib/starthere/superfluid-helium.js). Generated by tools/activities.py from curriculum/start-here.json:
   edit the data, not this file. demos/lib/starthere.js loads it. */
window.VDStartHere && VDStartHere({"q":"When pumped helium cools past 2.1768 K, does it boil harder or stop boiling?","q_es":"Cuando el helio bombeado se enfría por debajo de 2.1768 K, ¿hierve con más fuerza o deja de hervir?","setup":"","do":"A pump lowers the pressure over 100 g of liquid helium that starts at 4.22 K. Decide what the bubbles will do at the lambda point, 2.1768 K, then press <b>Reset</b> and watch the dewar and the <b>Temperature</b> readout until <b>Reached the lambda point</b> shows a time.","do_es":"Una bomba baja la presión sobre 100 g de helio líquido que empieza a 4.22 K. Decide qué harán las burbujas en el punto lambda, 2.1768 K, luego presiona <b>Reiniciar</b> y observa el dewar y la lectura <b>Temperatura</b> hasta que <b>Se llegó al punto lambda</b> muestre un tiempo.","see":"The bubbles stop at once, after 2.27 min, yet <b>Evaporation</b> still reads about 41 mg/s: the pump keeps taking vapor off the surface. Below the lambda point the liquid is helium II, which carries heat so well that no spot gets warm enough to make a bubble. By then <b>Boiled off</b> reads about 25 %, the liquid spent cooling the rest.","see_es":"Las burbujas se detienen de golpe, a los 2.27 min, pero <b>Evaporación</b> todavía marca unos 41 mg/s: la bomba sigue sacando vapor de la superficie. Debajo del punto lambda el líquido es helio II, que conduce el calor tan bien que ningún punto se calienta lo suficiente para formar una burbuja. Para entonces <b>Evaporado</b> marca cerca de 25 %, el líquido gastado en enfriar el resto.","explore":[{"setup":"set=sTf~1.4!sDT~5!labBlind~0!g%3AexpSeg~fountain!g%3Apresets~fountainLow","do":"<b>Fountain: a column</b>: a 12 cm tube with a plug of fine powder at the bottom stands in the bath at 1.40 K, and a heater warms the inside by 5.0 mK. Read <b>Column it holds</b>. Decide what 1.60 K and a 10.0 mK rise will do, then press <b>Fountain: it spouts</b> and read it again.","do_es":"<b>Fuente: una columna</b>: un tubo de 12 cm con un tapón de polvo fino abajo está en el baño a 1.40 K, y un calentador eleva el interior 5.0 mK. Lee <b>Columna que sostiene</b>. Decide qué harán 1.60 K y un aumento de 10.0 mK, luego presiona <b>Fuente: brota</b> y vuelve a leerla.","see":"6.75 cm, then 29.21 cm, far above the 12 cm rim, so the helium spouts out the top. Only the superfluid gets through the powder, and it flows toward the warmer side; the column is about h = SΔT/g, and the entropy S more than doubles, from 131.0 to 281.5 J/(kg·K), between 1.40 and 1.60 K, while ΔT doubles too.","see_es":"6.75 cm, luego 29.21 cm, muy por encima del borde de 12 cm, así que el helio brota por arriba. Solo el superfluido pasa por el polvo, y fluye hacia el lado más caliente; la columna es cerca de h = SΔT/g, y la entropía S crece más del doble, de 131.0 a 281.5 J/(kg·K), entre 1.40 y 1.60 K, mientras ΔT también se duplica."},{"setup":"set=sTt~1.3!labBlind~0!g%3AspdSeg~2!g%3AexpSeg~torsion!g%3Apresets~torsionLow","do":"<b>Spinning disks at 1.30 K</b>: 40 disks 0.20 mm apart twist back and forth on a fiber in the bath. Compare <b>Period</b> with <b>Bare disks</b>. Decide what the period does above the lambda point, then press <b>Spinning disks above the lambda point</b> and read it again.","do_es":"<b>Discos giratorios a 1.30 K</b>: 40 discos separados 0.20 mm giran de un lado a otro en una fibra dentro del baño. Compara <b>Periodo</b> con <b>Discos solos</b>. Decide qué hace el periodo por encima del punto lambda, luego presiona <b>Discos giratorios por encima del punto lambda</b> y vuelve a leerlo.","see":"20.470 s at 1.30 K, almost the bare disks' 20.000 s, then 28.672 s at 2.200 K. Only the normal fluid is dragged along by the disks: <b>Normal fluid fraction (table)</b> is 0.045 at 1.30 K and 1.000 above the lambda point, where all the helium turns with them. This is how Andronikashvili measured the two fluids in 1946.","see_es":"20.470 s a 1.30 K, casi los 20.000 s de los discos solos, luego 28.672 s a 2.200 K. Solo el fluido normal es arrastrado por los discos: <b>Fracción de fluido normal (tabla)</b> es 0.045 a 1.30 K y 1.000 por encima del punto lambda, donde todo el helio gira con ellos. Así midió Andronikashvili los dos fluidos en 1946."},{"setup":"set=sRate~10!sLeak~5!labBlind~0!g%3AexpSeg~he3!g%3Apresets~he3","do":"<b>Helium 3: cooling by freezing</b>: liquid helium 3 at 20 mK is squeezed so that some of it freezes. Freezing water gives off heat; decide whether this cell warms or cools, then watch <b>Temperature</b> and <b>Solid</b> until <b>Superfluid at</b> shows a time.","do_es":"<b>Helio 3: enfriamiento por congelación</b>: helio 3 líquido a 20 mK se comprime para que una parte se congele. El agua al congelarse libera calor; decide si esta celda se calienta o se enfría, luego observa <b>Temperatura</b> y <b>Sólido</b> hasta que <b>Superfluido a</b> muestre un tiempo.","see":"It cools, and the liquid turns superfluid after about 75 minutes, with about 12 % of it frozen. <b>Entropy S/R: solid, liquid</b> reads 0.693 (ln 2, from the solid's disordered nuclear spins) against under 0.09 for the liquid, so freezing takes heat out of the liquid: the Pomeranchuk effect, the method by which Osheroff, Richardson and Lee found superfluid helium 3 in 1972.","see_es":"Se enfría, y el líquido se vuelve superfluido a los 75 minutos aproximadamente, con cerca de 12 % congelado. <b>Entropía S/R: sólido, líquido</b> marca 0.693 (ln 2, por los espines nucleares desordenados del sólido) contra menos de 0.09 para el líquido, así que congelar saca calor del líquido: el efecto Pomeranchuk, el método con el que Osheroff, Richardson y Lee hallaron el helio 3 superfluido en 1972."}]});
